{"type":"item.completed","item":{"id":"item_17","type":"command_execution","command":"/bin/zsh -lc "jq 'keys' .lattice/story/actives/B-137a/checklist.json && jq '{items: [.items[] | {id,title,status,relatedDocs,verificationIntent}]}' .lattice/story/actives/B-137a/checklist.json"","aggregated_output":"[
