{
  "items": [
    {
      "id": "CHK-001",
      "title": "Persist and reconcile managed host-run lifecycle",
      "status": "done",
      "relatedDocs": [
        "docs/host-run-usage.md",
        "docs/requirements/decisions/session-ownership-and-write-leases.md"
      ],
      "verificationIntent": {
        "happy": [
          {
            "desc": "Submit one managed provider run, observe immutable spec and owner plus a successful worker claim, then observe monotonic snapshots and events ending in exactly one completed terminal receipt whose digest is returned by status; proves the durable lifecycle from submission to terminal truth.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-host-run-smoke.js",
              "selector": "managed-host-run-smoke PASS"
            }
          },
          {
            "desc": "Terminate the original caller after submission while the provider remains active, then query the returned runId from a new caller and observe the same execution continue to completed without a second provider spawn or replacement; proves caller lifetime is not run lifetime.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-host-run-smoke.js",
              "selector": "managed-host-run-smoke PASS"
            }
          }
        ],
        "edge": [
          {
            "desc": "Keep a real provider fixture silent longer than the legacy first-output and caller-observation boundaries while its process remains alive; repeated next-touch status calls must keep the same run running, report worker liveness separately from provider progress visibility, and never restart it merely because output is absent.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-host-run-smoke.js",
              "selector": "managed-host-run-smoke PASS"
            }
          },
          {
            "desc": "Crash the worker after claim and before terminal publication, then exercise status before and at the finite absolute deadline; reconciliation must preserve the original identity before deadline and eventually materialize definite timed_out or failed terminal truth rather than wait forever.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-host-run-smoke.js",
              "selector": "managed-host-run-smoke PASS"
            }
          }
        ],
        "adversarial": [
          {
            "desc": "Race multiple status, attach, cancel, and reconcile callers at the deadline; exclusive reconciliation and terminal creation must yield one immutable terminal receipt and all callers must converge on its exact digest.",
            "type": "logic",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-host-run-smoke.js",
              "selector": "managed-host-run-smoke PASS"
            }
          },
          {
            "desc": "Present missing, corrupt, partially-written, or identity-ambiguous runtime artifacts; the run must fail closed with honest residual unknown and replacementSafe false where cleanup cannot be proven, with no blind kill and no automatic replacement.",
            "type": "logic",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-host-run-smoke.js",
              "selector": "managed-host-run-smoke PASS"
            }
          },
          {
            "desc": "Race provider success against cancel and deadline expiry; exactly one authoritative terminal outcome wins, cleanup and residual facts are recorded, and replacementSafe becomes true only when the former execution can no longer write results or evidence.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-host-run-smoke.js",
              "selector": "managed-host-run-smoke PASS"
            }
          }
        ]
      }
    },
    {
      "id": "CHK-002",
      "title": "Expose submit, attach, status and cancel command surfaces",
      "status": "done",
      "relatedDocs": [
        "docs/host-run-usage.md",
        "docs/requirements/decisions/lattice-codex-command-boundary-execution-plan.md"
      ],
      "verificationIntent": {
        "happy": [
          {
            "desc": "Detached host_run returns only after the worker claim handshake with runId, running state, and deadlineAt; host_run_status --waitMs 30000 then long-polls that same identity and returns progress or its terminal receipt, while foreground host_run is submit-and-attach over the identical durable run.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-host-run-command-smoke.js",
              "selector": "managed-host-run-command-smoke PASS"
            }
          },
          {
            "desc": "Text and JSON foreground attachment preserve existing routing contracts: text host stdout streams once to stdout, JSON keeps stdout to one result object while transcript streams to stderr, and provider usage and passthrough errors remain honestly represented.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/host-run-usage-smoke.js",
              "selector": "host-run usage smoke passed (83 checks)"
            }
          }
        ],
        "edge": [
          {
            "desc": "Exercise waitMs at 0, 30000, and above 30000 plus a no-change interval; every call is bounded, values above the cap are rejected or capped explicitly, and a wait timeout reports the current non-terminal state without treating it as provider failure.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-host-run-command-smoke.js",
              "selector": "managed-host-run-command-smoke PASS"
            }
          },
          {
            "desc": "Call host_run_cancel repeatedly before claim, during execution, and after terminal completion; cancellation is idempotent, targets only the original run, and never creates a second terminal or changes an already authoritative terminal outcome.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-host-run-command-smoke.js",
              "selector": "managed-host-run-command-smoke PASS"
            }
          }
        ],
        "adversarial": [
          {
            "desc": "Inspect process arguments, persisted terminal and evidence artifacts, and post-claim runtime files; prompt and capability plaintext must not appear in argv or durable receipts, one-shot inputs must be mode 0600 and removed after claim, and only bounded redacted projections or digests may remain.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-host-run-command-smoke.js",
              "selector": "managed-host-run-command-smoke PASS"
            }
          },
          {
            "desc": "Supply unknown, malformed, path-traversal, cross-project, or stale runId values to status and cancel; commands must reject without reading or mutating another run and without spawning any provider process.",
            "type": "logic",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-host-run-command-smoke.js",
              "selector": "managed-host-run-command-smoke PASS"
            }
          },
          {
            "desc": "Kill the foreground attaching caller while its managed worker is active, then attach from a new caller; the original run must remain observable and complete once, proving CLI watchdog runtimeContinuation cannot translate caller loss into provider cancellation.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-host-run-e2e-smoke.js",
              "selector": "managed-host-run-e2e-smoke PASS"
            }
          }
        ]
      }
    },
    {
      "id": "CHK-003",
      "title": "Supervise provider processes portably and honestly",
      "status": "done",
      "relatedDocs": [
        "docs/host-run-usage.md",
        "docs/requirements/decisions/tier-c-crosshost-quorum-execution-plan.md"
      ],
      "verificationIntent": {
        "happy": [
          {
            "desc": "On POSIX, launch a fixture that creates a provider process tree in its own group, then complete or cancel it and prove TERM or KILL, reap, and residual probing leave no surviving group member; terminal records the exact cleanup facts.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-host-run-process-smoke.js",
              "selector": "managed-host-run-process-smoke PASS"
            }
          },
          {
            "desc": "Launch the Codex adapter through its documented exec stdin sentinel, write the prompt to stdin and close it, then preserve terminal usage parsing and configured provider timeout semantics; proves the managed adapter uses codex exec ... - rather than an undocumented implicit prompt path.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-host-run-command-smoke.js",
              "selector": "managed-host-run-command-smoke PASS"
            }
          }
        ],
        "edge": [
          {
            "desc": "Exercise a provider leader that exits while a child remains plus a provider that ignores TERM; supervision must check the process group, escalate to KILL after the bounded grace period, reap, and report any residual honestly rather than treating leader exit as full cleanup.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-host-run-process-smoke.js",
              "selector": "managed-host-run-process-smoke PASS"
            }
          },
          {
            "desc": "On an unsupported non-POSIX platform seam, submission must fail before spawn with an explicit unsupported-platform result; no partially supervised child or misleading replacementSafe true may be produced.",
            "type": "logic",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-host-run-process-smoke.js",
              "selector": "managed-host-run-process-smoke PASS"
            }
          },
          {
            "desc": "For observable and unobservable providers, snapshots must keep workerHeartbeatAt distinct from lastProviderProgressAt and providerProgressMode; a fresh worker heartbeat cannot be used as evidence of provider output or completion.",
            "type": "logic",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-host-run-process-smoke.js",
              "selector": "managed-host-run-process-smoke PASS"
            }
          }
        ],
        "adversarial": [
          {
            "desc": "Simulate PID or PGID reuse and a mismatched spawn fingerprint at reconcile time; the supervisor must not signal the ambiguous process, must record residual unknown and replacementSafe false, and must not authorize automatic replacement.",
            "type": "logic",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-host-run-process-smoke.js",
              "selector": "managed-host-run-process-smoke PASS"
            }
          },
          {
            "desc": "Keep the provider silent but alive until its explicit configured absolute deadline; silence alone must not signal or fail it, while the actual deadline must still trigger bounded group cleanup and timed_out terminal truth.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-host-run-process-smoke.js",
              "selector": "managed-host-run-process-smoke PASS"
            }
          },
          {
            "desc": "Make stdout and stderr flood, split structured usage records across chunks, and close passthrough sinks asynchronously; supervision must remain bounded, not crash on EPIPE, preserve honest usage availability, and still release process and admission resources.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/host-run-usage-smoke.js",
              "selector": "host-run usage smoke passed (83 checks)"
            }
          }
        ]
      }
    },
    {
      "id": "CHK-004",
      "title": "Enforce shared provider admission independent of usage-ledger mode",
      "status": "done",
      "relatedDocs": [
        "docs/host-run-usage.md",
        "docs/requirements/decisions/lattice-llm-usage-ledger-execution-plan.md",
        "docs/requirements/decisions/multi-host-keyword-candidate-spec-routing-execution-plan.md"
      ],
      "verificationIntent": {
        "happy": [
          {
            "desc": "With LATTICE_USAGE_LEDGER disabled and the shared cap set to one, start one long provider run and attempt a second launch from every migrated provider surface; exactly one holds admission and every concurrent launch site refuses pre-spawn until the slot is released.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/provider-process-registry-smoke.js",
              "selector": "provider-process-registry-smoke PASS"
            }
          },
          {
            "desc": "With the ledger enabled, provider admission remains the same while hard-budget decisions, blocked rows, final provider usage, and append failures retain their existing fail-closed and diagnostic-honesty semantics.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/host-run-usage-smoke.js",
              "selector": "host-run usage smoke total passed"
            }
          }
        ],
        "edge": [
          {
            "desc": "Race more contenders than the cap against fixed numbered slot creation, then crash a holder; atomic admission permits no oversubscription, dead or orphaned slots are reclaimed under their documented rules, and an old but live holder is never reclaimed by age alone.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/provider-process-registry-smoke.js",
              "selector": "provider-process-registry-smoke PASS"
            }
          },
          {
            "desc": "Lower the configured cap while high-index runs are live and then release them; existing holders drain without deletion, new admissions use only the lowered range, and token-guarded late release cannot delete a reclaimed and re-acquired slot.",
            "type": "logic",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/provider-process-registry-smoke.js",
              "selector": "provider-process-registry-smoke PASS"
            }
          },
          {
            "desc": "Feed candidate-spec and usage parsing streams with valid candidates, chunks over 64 KiB, post-candidate overflow, and no first candidate; live per-chunk output remains intact while retained candidate state follows discard-all overflow and null-first-output rules exactly.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/host-run-usage-smoke.js",
              "selector": "host-run usage smoke total passed"
            }
          }
        ],
        "adversarial": [
          {
            "desc": "Enumerate every production provider execution surface and prove it has exactly one registry classification: managed, admission_only, adapter_only, or readiness_probe; legacy_unmanaged is explicitly reserved and must be empty. A new direct provider spawn or unclassified surface must make the contract test fail.",
            "type": "logic",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/provider-process-registry-smoke.js",
              "selector": "provider-process-registry-smoke PASS"
            }
          },
          {
            "desc": "Corrupt, truncate, or replace slot metadata during acquire and release races; admission must fail closed or reclaim only after re-verifying ownership, and a stale releaser must never unlink a newer holder slot.",
            "type": "logic",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/provider-process-registry-smoke.js",
              "selector": "provider-process-registry-smoke PASS"
            }
          },
          {
            "desc": "Force ledger append failures for allowed, blocked, and final records while provider admission is active; no output may claim a row was recorded when it was not, but slot acquisition and release must still be enforced independently.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/host-run-usage-smoke.js",
              "selector": "host-run usage smoke total passed"
            }
          }
        ]
      }
    },
    {
      "id": "CHK-005",
      "title": "Route cross-host review through managed execution",
      "status": "done",
      "relatedDocs": [
        "docs/requirements/decisions/tier-c-crosshost-quorum-execution-plan.md",
        "docs/requirements/decisions/review-assurance-floor-execution-plan.md"
      ],
      "verificationIntent": {
        "happy": [
          {
            "desc": "Run cross_host_review through the privileged managed profile with a fixed material snapshot and valid structured Codex verdict; it must attach to the managed terminal receipt, validate the verdict, submit the host-B result, and preserve an agreeing joint pass without exposing raw provider output.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/cross-host-review-smoke.js",
              "selector": "cross_host_review smoke passed (25 checks)"
            }
          },
          {
            "desc": "End the cross_host_review caller while its provider is still working, then resume by the managed run identity; the same review completes and is consumed once, with no duplicate Codex launch and no verdict loss caused by the caller boundary.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/cross-host-review-smoke.js",
              "selector": "cross_host_review smoke passed (25 checks)"
            }
          }
        ],
        "edge": [
          {
            "desc": "Return malformed JSON, schema-invalid verdicts, a mismatched material hash, empty output, and abnormal provider exit; each must synthesize the existing blocked host-B verdict and fail closed while retaining only bounded digest or redacted diagnostics.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/cross-host-review-smoke.js",
              "selector": "cross_host_review smoke passed (25 checks)"
            }
          },
          {
            "desc": "Exercise configured cross_host_review timeout ceilings and bounded attempts at their exact boundaries; migration to ManagedHostRun must preserve the existing ceiling, attempt count, and joint-decision behavior while replacing only execution supervision.",
            "type": "logic",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/cross-host-review-smoke.js",
              "selector": "cross_host_review smoke passed (25 checks)"
            }
          },
          {
            "desc": "Keep Codex silent but alive inside the policy ceiling; cross_host_review must report the managed run as active rather than converting silence into codex_review_no_parseable_verdict before the configured deadline.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/cross-host-review-smoke.js",
              "selector": "cross_host_review smoke passed (25 checks)"
            }
          }
        ],
        "adversarial": [
          {
            "desc": "Try to bypass the privileged profile with a caller-supplied command, cwd, environment, output path, or verdict binding; cross_host_review remains owner of snapshot, policy, redacted environment, and verdict validation, and ManagedHostRun executes only the opaque approved profile.",
            "type": "logic",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/cross-host-review-smoke.js",
              "selector": "cross_host_review smoke passed (25 checks)"
            }
          },
          {
            "desc": "Race material drift and cancellation after submission but before verdict persistence; stale or cancelled terminal output cannot be submitted as a current host verdict, and the joint decision remains blocked.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/cross-host-review-smoke.js",
              "selector": "cross_host_review smoke passed (25 checks)"
            }
          },
          {
            "desc": "Prove cross_host_review no longer owns a second direct Codex spawn or kill stack by a source-contract test that fails if production execution bypasses ManagedHostRun.",
            "type": "logic",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/cross-host-review-smoke.js",
              "selector": "cross_host_review smoke passed (25 checks)"
            }
          }
        ]
      }
    },
    {
      "id": "CHK-006",
      "title": "Bind formal reviewer evidence to exact managed receipts",
      "status": "done",
      "relatedDocs": [
        "docs/requirements/decisions/review-run-binding-race.md",
        "docs/requirements/decisions/review-assurance-floor-execution-plan.md",
        "docs/requirements/decisions/proof-admissibility-hardening-execution-plan.md"
      ],
      "verificationIntent": {
        "happy": [
          {
            "desc": "E2E pass path: the dispatched provider reviewer, while the managed run is active, authors exactly one immutable profile-bound proposal containing its pass verdict, registered reviewer identity, truthful readManifest/readLog, and exact story/reviewRun/lane/provider/prompt-envelope/material bindings; it writes no final ReviewPass. A successful terminal exclusively seals the proposal and append-only journal digests before managed_review_evidence_import accepts only the runId/receipt, and the importer creates the existing ReviewPass without changing verdict or authorship while preserving reviewer, lane, reviewRun and read provenance; the REVIEW gate accepts that exact current composite evidence.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-review-evidence-smoke.js",
              "selector": "managed-review-evidence-smoke PASS"
            }
          },
          {
            "desc": "E2E finding path: the provider reviewer authors immutable findings and read provenance in one sealed proposal, successful terminal precedes import, and the mechanical importer reproduces each provider-authored finding exactly with its reviewer/reviewRun/lane/read provenance; verified open high or critical findings remain visible to the normal REVIEW blocking predicates and cannot be replaced by a controller-authored pass.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-review-evidence-smoke.js",
              "selector": "managed-review-evidence-smoke PASS"
            }
          },
          {
            "desc": "E2E admissibility path: import-time admission and later REVIEW-gate consumption both resolve the managed receipt/composite evidence through the same shared Proof Admissibility artifact registry, intake normalization, evaluator, producer/scope/claim/consumer/material policies, and canonical reason-code vocabulary; an authentic control receives the same admissible classification at both boundaries.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/proof-admissibility-registry-smoke.js",
              "selector": "proof-admissibility-registry-smoke PASS"
            }
          }
        ],
        "edge": [
          {
            "desc": "A missing terminal, pre-terminal proposal, failed/cancelled/timed_out/nonzero terminal, incomplete or ambiguous cleanup, missing proposal, or multiple proposals must receive the matching canonical Proof Admissibility refusal and import no ReviewPass/Finding; diagnostic or degraded evidence remains explicit and cannot upgrade to normal managed assurance.",
            "type": "logic",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-review-evidence-smoke.js",
              "selector": "managed-review-evidence-smoke PASS"
            }
          },
          {
            "desc": "After a valid import, change materialHash, storyFilesHash, head lineage, prompt envelope, review round, lane policy, provider binding, proposal bytes or journal bytes; both a fresh import attempt and REVIEW-gate revalidation must fail closed through the shared evaluator with the same canonical stale/integrity/consumer reason family rather than trust a persisted boolean.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-review-evidence-smoke.js",
              "selector": "managed-review-evidence-smoke PASS"
            }
          },
          {
            "desc": "Replay the same authentic runId/receipt and race two importers; import is idempotent and converges on one exact ReviewPass or finding set with unchanged provider reviewer/read provenance, while a different receipt cannot supersede or rewrite the already imported provider proposal.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-review-evidence-smoke.js",
              "selector": "managed-review-evidence-smoke PASS"
            }
          },
          {
            "desc": "Native-host reviewer lanes retain their existing signed ReviewRun/pass/finding path, while an explicitly configured degraded-single-host result remains local and non-authority, names the absent managed composite evidence, and is never relabeled as provider-authored managed or two-host assurance.",
            "type": "logic",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-review-evidence-smoke.js",
              "selector": "managed-review-evidence-smoke PASS"
            }
          }
        ],
        "adversarial": [
          {
            "desc": "Controller non-impersonation E2E: after provider proposal creation, attempt every controller-supplied verdict, note, finding, evidenceState, reviewer identity, readManifest/readLog or provenance override and attempt direct controller final review_pass_set/finding_add as the managed reviewer; the importer exposes no such override surface, rejects altered bytes or identity, preserves the provider-authored proposal exactly, and never records the controller as reviewer.",
            "type": "cli",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-review-evidence-smoke.js",
              "selector": "managed-review-evidence-smoke PASS"
            }
          },
          {
            "desc": "Tamper each bound field independently, forge runId/terminal/proposal/journal digests, append or truncate journal bytes, swap receipts across story/reviewRun/lane/provider/prompt/material, or replay stale material; every variant is rejected by both import admission and REVIEW consumption while the byte-authentic control is accepted.",
            "type": "logic",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/managed-review-evidence-smoke.js",
              "selector": "managed-review-evidence-smoke PASS"
            }
          },
          {
            "desc": "Shared-evaluator mutation contract: delete or bypass the shared Proof Admissibility intake/evaluator call at either import-time or REVIEW-gate consumption, hard-code an allow result, introduce a managed-review-only registry or parallel evaluator, or diverge a canonical reason code; the source/registry contract and mutation smoke must fail for every mutant, proving both boundaries consume one registry/intake/evaluator instead of mirrored special cases.",
            "type": "logic",
            "priority": "must",
            "verification": {
              "command": "node packages/main/dist/tasks/proof-admissibility-registry-smoke.js",
              "selector": "proof-admissibility-registry-smoke PASS"
            }
