export function readManagedHostRunResult(root: string, runId: string): HostRunResult | null {
  const paths = pathsFor(root, runId);
  return existsSync(paths.result) ? readJson<HostRunResult>(paths.result) : null;
}

export function readManagedHostRunBinding(root: string, runId: string): ManagedHostRunBindingProjection {
  const paths = pathsFor(root, runId);
  // B-137a:F-127 — same archive-backed fallback managedHostRunReceipt already
  // has. Terminal-retention GC archives the receipt and then deletes the run
  // directory, so without this the spec/owner reads below throw ENOENT and
  // verifyManagedReviewEvidence fails closed on evidence that was legitimately
  // imported while the run still existed. Verified empirically: after
  // removeManagedHostRunRuntime the pre-fix reader threw ENOENT.
  if (!existsSync(paths.spec)) {
    const archivePath = managedHostRunReceiptArchivePath(root, runId);
    if (existsSync(archivePath)) {
      const archive = readJson<ManagedHostRunReceiptArchive>(archivePath);
      if (archive.schemaVersion !== 'lattice.managed_host_run_receipt_archive.v1' || archive.runId !== runId) {
        throw new Error(`managed host run ${runId}: archived binding is corrupt`);
      }
      if (archive.binding && archive.binding.runId === runId) return archive.binding;
      // Pre-F-127 archive: no binding was captured, so fail closed exactly as
      // before rather than fabricating one.
      throw new Error(
        `managed host run ${runId}: run directory was reclaimed by terminal retention and the archive predates `
        + 'binding capture, so the evidence binding cannot be reconstructed',
      );
    }
  }
  const spec = readJson<ManagedHostRunSpec>(paths.spec);
  const owner = readJson<ManagedHostRunOwner>(paths.owner);
  return {
    runId: spec.runId,
    host: spec.host,
    storyId: spec.storyId,
    phase: spec.phase,
    agentType: spec.agentType,
    reviewRunId: spec.reviewRunId,
    lane: spec.lane,
    cwd: spec.cwd,
    deadlineAt: spec.deadlineAt,
    timeoutMs: spec.timeoutMs,
    projectRootHash: spec.projectRootHash,
    profile: spec.profile,
    promptDigest: owner.promptDigest,
    reviewBinding: spec.reviewBinding ?? null,
  };
}

/** Resolve the immutable Story subject used by the CLI ownership gate. */
export function managedHostRunStoryIdForOwnership(root: string, runId: string): string | null {
  const paths = pathsFor(root, runId);
  if (!existsSync(paths.spec) || !existsSync(paths.owner)) return null;
  const specText = readFileSync(paths.spec, 'utf8');
  const spec = JSON.parse(specText) as ManagedHostRunSpec;
  const owner = readJson<ManagedHostRunOwner>(paths.owner);
  if (spec.schemaVersion !== MANAGED_HOST_RUN_SCHEMA_VERSION
    || owner.schemaVersion !== MANAGED_HOST_RUN_SCHEMA_VERSION
    || spec.runId !== runId
    || owner.runId !== runId
    || owner.specDigest !== sha256(specText)) {
    throw new Error(`managed host run ${runId}: immutable ownership subject binding mismatch`);
  }
  return typeof spec.storyId === 'string' && spec.storyId.trim().length > 0 ? spec.storyId.trim() : null;
}

type ManagedReviewFinalProposalInput = Omit<ManagedReviewEvidenceProposal, 'schemaVersion' | 'runId' | 'authoredAt'>;

function readValidManagedReviewEvidenceProposal(
  root: string,
  runId: string,
  spec: ManagedHostRunSpec,
): ManagedReviewEvidenceProposal | null {
  try {
    const proposal = readManagedReviewEvidenceProposal(root, runId);
    if (!proposal
      || proposal.schemaVersion !== 'lattice.managed_review_evidence_proposal.v1'
      || proposal.runId !== runId
      || proposal.storyId !== spec.storyId
      || proposal.providerAgent !== spec.agentType
      || proposal.lane !== spec.lane
      || proposal.reviewRunId !== spec.reviewRunId
      || !Number.isFinite(Date.parse(proposal.authoredAt))) {
      return null;
    }
    if (proposal.conclusion === 'pass') {
      if (typeof proposal.note !== 'string' || proposal.note.trim().length < 10
        || (proposal.findings !== undefined && (!Array.isArray(proposal.findings) || proposal.findings.length > 0))) {
        return null;
      }
    } else if (proposal.conclusion === 'findings') {
      if (typeof proposal.note === 'string' && proposal.note.trim().length > 0
        || !Array.isArray(proposal.findings)
        || proposal.findings.length === 0
        || !proposal.findings.every(isStrictManagedReviewFindingProposal)) {
        return null;
      }
    } else {
      return null;
    }
    normalizeReviewerReadManifest(proposal.readManifest);
    if (proposal.readLog !== undefined) normalizeReviewerReadLogEvidence(proposal.readLog);
    if (proposal.readDiagnostics !== undefined) normalizeReviewerReadDiagnostics(proposal.readDiagnostics);
    return proposal;
  } catch {
    return null;
  }
}

function parseManagedReviewFinalProposal(result: HostRunResult): ManagedReviewFinalProposalInput {
  if (result.finalAssistantResultTruncated) {
    throw new Error('managed_review_final_result_oversize');
  }
  if (result.finalAssistantResultCount > 1) {
    throw new Error('managed_review_final_result_multiple');
  }
  if (result.finalAssistantResultCount !== 1 || result.finalAssistantResult === null) {
    throw new Error('managed_review_final_result_missing');
  }
  const classification = classifyManagedReviewFinalEnvelope(result.finalAssistantResult);
  if (classification.kind !== 'valid') throw new Error('managed_review_final_result_malformed');
  const envelope = classification.envelope;
  const conclusion = envelope.conclusion;
  return {
    storyId: envelope.storyId,
    providerAgent: envelope.providerAgent,
    lane: envelope.lane,
    reviewRunId: envelope.reviewRunId,
    conclusion,
    ...(conclusion === 'pass' ? { note: envelope.note as string | undefined } : {
      findings: envelope.findings as ManagedReviewEvidenceFindingProposal[] | undefined,
    }),
    readManifest: envelope.readManifest as ReviewerReadManifest,
    ...(envelope.readLog !== undefined ? { readLog: envelope.readLog as ReviewerReadLogEvidence } : {}),
    ...(envelope.readDiagnostics !== undefined ? { readDiagnostics: envelope.readDiagnostics as ReviewerReadDiagnostic[] } : {}),
  };
}

export function writeManagedReviewEvidenceProposal(args: {
  root: string;
  runId: string;
  proposal: Omit<ManagedReviewEvidenceProposal, 'schemaVersion' | 'runId' | 'authoredAt'>;
  environment?: NodeJS.ProcessEnv;
  providerInvocationPid?: number;
  providerInvocationAttestation?: ManagedReviewProposalInvocationAttestation;
}): ManagedReviewEvidenceProposal {
  const paths = pathsFor(args.root, args.runId);
  const spec = readJson<ManagedHostRunSpec>(paths.spec);
  const owner = readJson<ManagedHostRunOwner>(paths.owner);
  const snapshot = readJson<ManagedHostRunSnapshot>(paths.snapshot);
  const environment = args.environment ?? process.env;
  if (args.providerInvocationPid === undefined
    && args.providerInvocationAttestation === undefined
    && environment.LATTICE_MANAGED_HOST_RUN_ID !== args.runId) {
    throw new Error('managed_review_proposal_set: active managed-run capability is missing or mismatched');
  }
  if (readTerminal(paths) || snapshot.state !== 'running') {
    throw new Error('managed_review_proposal_set: proposal is accepted only while the managed provider run is active');
  }
  if (spec.profile !== 'managed_reviewer' || !spec.reviewBinding) {
    throw new Error('managed_review_proposal_set: run is not a formal managed_reviewer execution');
  }
  if (!spec.storyId || !spec.reviewRunId || !spec.lane) {
    throw new Error('managed_review_proposal_set: managed reviewer run is not bound to storyId/reviewRunId/lane');
  }
  const environmentAuthorized = (
    environment.LATTICE_MANAGED_REVIEW_PROPOSAL_CAPABILITY === undefined
      ? false
      : sha256(environment.LATTICE_MANAGED_REVIEW_PROPOSAL_CAPABILITY) === owner.capabilityDigest
        && environment.LATTICE_AGENT === spec.agentType
  );
  const providerInvocationAuthorized = args.providerInvocationPid !== undefined
    && providerInvocationMatches(paths, {
      storyId: args.proposal.storyId,
      providerAgent: args.proposal.providerAgent,
      lane: args.proposal.lane,
      reviewRunId: args.proposal.reviewRunId,
    }, args.providerInvocationPid);
  const descriptorInvocationAuthorized = args.providerInvocationAttestation !== undefined
    && verifyManagedReviewProposalInvocationAttestation(paths, {
      storyId: args.proposal.storyId,
      providerAgent: args.proposal.providerAgent,
      lane: args.proposal.lane,
      reviewRunId: args.proposal.reviewRunId,
    }, args.providerInvocationAttestation);
  if (!environmentAuthorized && !providerInvocationAuthorized && !descriptorInvocationAuthorized) {
    throw new Error('managed_review_proposal_set: provider proposal capability or agent identity is missing or mismatched');
  }
  if (
    args.proposal.storyId !== spec.storyId
    || args.proposal.reviewRunId !== spec.reviewRunId
    || args.proposal.lane !== spec.lane
    || args.proposal.providerAgent !== spec.agentType
  ) {
    throw new Error('managed_review_proposal_set: proposal provenance does not match the sealed managed run spec');
  }
  const conclusion = args.proposal.conclusion;
  const findings = args.proposal.findings ?? [];
  const note = args.proposal.note?.trim() ?? '';
  if (conclusion === 'pass') {
    if (note.length < 10 || findings.length > 0) {
      throw new Error('managed_review_proposal_set: pass requires note >= 10 chars and no findings');
    }
  } else if (conclusion === 'findings') {
    if (findings.length === 0 || note.length > 0) {
      throw new Error('managed_review_proposal_set: findings conclusion requires at least one finding and no pass note');
    }
  } else {
    throw new Error('managed_review_proposal_set: conclusion must be pass or findings');
  }
  const normalizedFindings = findings.map((finding, index) => {
    if (!isStrictManagedReviewFindingProposal(finding)) {
      throw new Error(`managed_review_proposal_set: findings[${index}] must match the strict managed finding schema`);
    }
    return {
      ...finding,
      desc: finding.desc.trim(),
      ...(finding.files ? { files: [...new Set(finding.files.map(value => value.trim()).filter(Boolean))].sort() } : {}),
    };
  });
  const proposal: ManagedReviewEvidenceProposal = {
    schemaVersion: 'lattice.managed_review_evidence_proposal.v1',
    runId: args.runId,
    storyId: spec.storyId,
    providerAgent: spec.agentType,
    lane: spec.lane,
    reviewRunId: spec.reviewRunId,
    authoredAt: new Date().toISOString(),
    conclusion,
    ...(conclusion === 'pass' ? { note } : { findings: normalizedFindings }),
    readManifest: normalizeReviewerReadManifest(args.proposal.readManifest),
    ...(args.proposal.readLog ? { readLog: normalizeReviewerReadLogEvidence(args.proposal.readLog) } : {}),
    ...(args.proposal.readDiagnostics ? { readDiagnostics: normalizeReviewerReadDiagnostics(args.proposal.readDiagnostics) } : {}),
  };
  withTerminalAuthorityLock(paths, () => {
    if (readTerminal(paths)) {
      throw new Error('managed_review_proposal_set: proposal is accepted only while the managed provider run is active');
    }
    if (!writeExclusive(paths.evidenceProposal, proposal)) {
      throw new Error('managed_review_proposal_set: this run already has an immutable evidence proposal');
    }
    appendFileSync(paths.events, `${canonicalJson({
      schemaVersion: MANAGED_HOST_RUN_SCHEMA_VERSION,
      runId: args.runId,
      at: proposal.authoredAt,
      type: 'review_evidence_proposed',
      detail: { conclusion, proposalDigest: digestFile(paths.evidenceProposal) },
    })}\n`, { encoding: 'utf8', mode: 0o600 });
  });
  return proposal;
}

export function readManagedReviewEvidenceProposal(root: string, runId: string): ManagedReviewEvidenceProposal | null {
  const paths = pathsFor(root, runId);
  if (existsSync(paths.evidenceProposal)) {
    return readJson<ManagedReviewEvidenceProposal>(paths.evidenceProposal);
  }
  // B-137a:F-127 — archive fallback for a run whose directory was reclaimed by
  // terminal-retention GC. The archived body is only accepted when it re-digests
  // to the SEALED receipt's evidenceProposalDigest, so a tampered or swapped
  // archive is rejected instead of trusted; a missing spec.json distinguishes a
  // genuinely reclaimed run from a merely absent proposal on a live run.
  if (!existsSync(paths.spec)) {
    const archivePath = managedHostRunReceiptArchivePath(root, runId);
    if (existsSync(archivePath)) {
      const archive = readJson<ManagedHostRunReceiptArchive>(archivePath);
      if (archive.schemaVersion !== 'lattice.managed_host_run_receipt_archive.v1' || archive.runId !== runId) {
        throw new Error(`managed host run ${runId}: archived proposal is corrupt`);
      }
      const archivedText = archive.evidenceProposalText ?? null;
      if (archivedText === null) return null;
      const expected = archive.receipt.evidenceProposalDigest;
      if (expected === null || sha256(archivedText) !== expected) {
        throw new Error(
          `managed host run ${runId}: archived proposal does not match the sealed receipt digest`,
        );
      }
      return JSON.parse(archivedText) as ManagedReviewEvidenceProposal;
    }
  }
  return null;
}

function importSealMatchesLiveContract(runId: string, bindingText: string, sealText: string): boolean {
  try {
    const seal = JSON.parse(sealText) as Record<string, unknown>;
    return seal.schemaVersion === 'lattice.managed_review_evidence_binding_seal.v1'
      && seal.runId === runId
      && seal.bindingDigest === sha256(bindingText);
  } catch {
    return false;
  }
}

/**
 * B-137a:F-127 — the import-seal pair for a run, archive-backed so an imported
 * evidence record stays verifiable after terminal-retention GC. Returns the raw
 * texts (the caller compares them exactly as it would the on-disk files) or null
 * when neither the live files nor an archive carrying them exist. An archived
 * pair is admitted only after the binding re-digests to evidenceBindingDigest
 * and the seal's schemaVersion, runId, and bindingDigest match the live path.
 */
export function readManagedReviewImportSeal(
  root: string,
  runId: string,
): { bindingText: string; sealText: string } | null {
  const paths = pathsFor(root, runId);
  if (existsSync(paths.evidenceBinding) && existsSync(paths.evidenceBindingSeal)) {
    return {
      bindingText: readFileSync(paths.evidenceBinding, 'utf8'),
      sealText: readFileSync(paths.evidenceBindingSeal, 'utf8'),
    };
  }
  if (!existsSync(paths.spec)) {
    const archivePath = managedHostRunReceiptArchivePath(root, runId);
    if (existsSync(archivePath)) {
      const archive = readJson<ManagedHostRunReceiptArchive>(archivePath);
      if (archive.schemaVersion !== 'lattice.managed_host_run_receipt_archive.v1' || archive.runId !== runId) {
        throw new Error(`managed host run ${runId}: archived import seal is corrupt`);
      }
      const bindingText = archive.evidenceBindingText ?? null;
      const sealText = archive.evidenceBindingSealText ?? null;
      if (bindingText === null || sealText === null) return null;
      const expected = archive.evidenceBindingDigest;
      if (expected === null || sha256(bindingText) !== expected) {
        throw new Error(
          `managed host run ${runId}: archived import seal does not match its recorded digest`,
        );
      }
      if (!importSealMatchesLiveContract(runId, bindingText, sealText)) {
        throw new Error(
          `managed host run ${runId}: archived import seal schema, runId, or bindingDigest is invalid`,
        );
      }
      return { bindingText, sealText };
    }
  }
  return null;
}

export function managedHostRunReceipt(root: string, runId: string): ManagedHostRunReceipt {
  const paths = pathsFor(root, runId);
  const terminal = readTerminal(paths);
  if (!terminal) {
    const archivePath = managedHostRunReceiptArchivePath(root, runId);
    if (existsSync(archivePath)) {
      const archive = readJson<ManagedHostRunReceiptArchive>(archivePath);
      const { receiptId, ...receiptPayload } = archive.receipt;
      if (archive.schemaVersion !== 'lattice.managed_host_run_receipt_archive.v1'
        || archive.runId !== runId
        || archive.receipt.runId !== runId
        || receiptId !== sha256(canonicalJson(receiptPayload))) {
        throw new Error(`managed host run ${runId}: archived terminal receipt is corrupt`);
      }
      return archive.receipt;
    }
    throw new Error(`managed host run ${runId}: terminal receipt is not available`);
  }
/**
 * Canonical, ledger-independent provider-process capacity registry.
 *
 * Admission is an atomic exclusive create of one of a fixed set of numbered
 * slots. Usage accounting may be disabled; this registry never is. A recorded
 * live pid is never reclaimed because of age alone, and release is guarded by
 * the acquire-minted ownership token.
 */

import { randomUUID } from 'node:crypto';
import {
  mkdirSync,
  readdirSync,
  readFileSync,
  statSync,
  unlinkSync,
  renameSync,
  writeFileSync,
} from 'node:fs';
import { hostname } from 'node:os';
import { dirname, join } from 'node:path';
import {
  acquireMkdirLock,
  type ExistingMkdirLockSnapshot,
  type ExistingMkdirLockState,
} from './mkdir-lock.js';
import { resolveCanonicalRuntimeProjectRoot } from './runtime-artifact-registry.js';

const PROVIDER_PROCESS_SLOTS_RELATIVE = join('.lattice', 'runtime', 'provider-process-slots');
export const PROVIDER_PROCESS_MAX_CONCURRENT_DEFAULT = 4;
export const PROVIDER_PROCESS_SLOT_STALE_MS_DEFAULT = 6 * 60 * 60 * 1000;

export interface ProviderProcessLiveDescriptor {
  pid: number;
  startedAt: string;
  host: string;
  storyId: string | null;
  agentType: string;
}

export interface ProviderProcessSlotMeta extends ProviderProcessLiveDescriptor {}

export interface ProviderProcessSlotFileMeta extends ProviderProcessSlotMeta {
  token: string;
  providerPid?: number;
  providerPgid?: number;
  providerSpawnedAt?: string;
  providerStartFingerprint?: string;
  providerProcessGroupIsolated?: boolean;
}

export interface AcquiredProviderProcessSlot {
  file: string;
  token: string;
}

export interface ProviderRegistryLockTiming {
  deadlineMs?: number;
  staleMs?: number;
  pollMs?: number;
}

export interface ProviderRegistryMutationOps {
  unlink(file: string): void;
}

const DEFAULT_PROVIDER_REGISTRY_MUTATION_OPS: ProviderRegistryMutationOps = {
  unlink: unlinkSync,
};

type SlotOccupant =
  | { state: 'valid'; pid: number; token: string | null; meta: Record<string, unknown> }
  | { state: 'corrupt'; identity: string }
  | { state: 'missing' };

function corruptSlotIdentity(file: string, raw: string): string {
  try {
    const stat = statSync(file);
    return `${stat.dev}:${stat.ino}:${stat.size}:${stat.mtimeMs}:${raw}`;
  } catch (error) {
    return `unstatable:${(error as NodeJS.ErrnoException).code ?? 'unknown'}:${raw}`;
  }
}

function ownString(value: Record<string, unknown>, key: string): string | null {
  if (!Object.prototype.hasOwnProperty.call(value, key)) return null;
  return typeof value[key] === 'string' ? value[key] as string : null;
}

function ownNumber(value: Record<string, unknown>, key: string): number | null {
  if (!Object.prototype.hasOwnProperty.call(value, key)) return null;
  return typeof value[key] === 'number' && Number.isInteger(value[key]) ? value[key] as number : null;
}

function readSlotOccupant(file: string): SlotOccupant {
  let raw: string;
  try {
    raw = readFileSync(file, 'utf8');
  } catch (error) {
    return (error as NodeJS.ErrnoException).code === 'ENOENT'
      ? { state: 'missing' }
      : { state: 'corrupt', identity: corruptSlotIdentity(file, '') };
  }
  try {
    const parsed = JSON.parse(raw) as unknown;
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
      return { state: 'corrupt', identity: corruptSlotIdentity(file, raw) };
    }
    const meta = parsed as Record<string, unknown>;
    const pid = ownNumber(meta, 'pid');
    if (pid === null) return { state: 'corrupt', identity: corruptSlotIdentity(file, raw) };
    return { state: 'valid', pid, token: ownString(meta, 'token'), meta };
  } catch {
    return { state: 'corrupt', identity: corruptSlotIdentity(file, raw) };
  }
}

function sameSlotOccupant(left: SlotOccupant, right: SlotOccupant): boolean {
  if (left.state !== right.state) return false;
  if (left.state === 'valid' && right.state === 'valid') {
    return left.pid === right.pid && left.token === right.token;
  }
  if (left.state === 'corrupt' && right.state === 'corrupt') {
    return left.identity === right.identity;
  }
  return true;
}

function pidAlive(pid: number): boolean {
  if (!Number.isInteger(pid) || pid <= 0) return false;
  try {
    process.kill(pid, 0);
    return true;
  } catch (error) {
    return (error as NodeJS.ErrnoException).code === 'EPERM';
  }
}

function processGroupAlive(pgid: number): boolean {
  if (!Number.isInteger(pgid) || pgid <= 1 || process.platform === 'win32') return false;
  try {
    process.kill(-pgid, 0);
    return true;
  } catch (error) {
    return (error as NodeJS.ErrnoException).code === 'EPERM';
  }
}

function slotReclaimable(occupant: SlotOccupant, file: string, now: number, staleMs: number): boolean {
  if (occupant.state === 'missing') return true;
  if (occupant.state === 'valid') {
    const isolated = occupant.meta.providerProcessGroupIsolated === true;
    const providerPgid = ownNumber(occupant.meta, 'providerPgid');
    // Once the admission has transferred to an isolated provider group, the
    // group—not the supervising worker—is the capacity owner. A crashed worker
    // may leave children alive, so reclaim only after the exact PGID disappears.
    if (isolated && providerPgid !== null && processGroupAlive(providerPgid)) return false;
    return !pidAlive(occupant.pid);
  }
  try {
    const ageMs = now - statSync(file).mtimeMs;
    return !Number.isFinite(ageMs) || ageMs > staleMs;
  } catch {
    // Fail closed: an existing slot we cannot stat still occupies capacity.
    return false;
  }
}

export function providerProcessSlotsDir(root: string): string {
  return join(resolveCanonicalRuntimeProjectRoot(root), PROVIDER_PROCESS_SLOTS_RELATIVE);
}

export function resolveProviderProcessMaxConcurrent(env: NodeJS.ProcessEnv): number {
  const raw = env.LATTICE_HOST_RUN_MAX_CONCURRENT;
  if (typeof raw !== 'string' || raw.trim().length === 0) return PROVIDER_PROCESS_MAX_CONCURRENT_DEFAULT;
  const value = Number(raw.trim());
  return Number.isFinite(value) && Number.isInteger(value) && value > 0
    ? value
    : PROVIDER_PROCESS_MAX_CONCURRENT_DEFAULT;
}

export function resolveProviderProcessSlotStaleMs(env: NodeJS.ProcessEnv): number {
  const raw = env.LATTICE_HOST_RUN_SLOT_STALE_MS;
  if (typeof raw !== 'string' || raw.trim().length === 0) return PROVIDER_PROCESS_SLOT_STALE_MS_DEFAULT;
  const value = Number(raw.trim());
  return Number.isFinite(value) && value > 0 ? value : PROVIDER_PROCESS_SLOT_STALE_MS_DEFAULT;
}

export function writeProviderProcessSlotExclusive(
  file: string,
  meta: ProviderProcessSlotFileMeta,
): boolean {
  try {
    writeFileSync(file, JSON.stringify(meta), { encoding: 'utf8', flag: 'wx', mode: 0o600 });
    return true;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'EEXIST') return false;
    throw error;
  }
}

function scanLiveProviderProcessSlotsUnlocked(
  dir: string,
  now: number,
  staleMs: number,
): ProviderProcessLiveDescriptor[] {
  let entries: string[];
  try {
    entries = readdirSync(dir);
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return [];
    const code = (error as NodeJS.ErrnoException).code ?? 'unknown';
    const detail = error instanceof Error ? error.message : String(error);
    throw new Error(`provider-process-registry slots directory unreadable (${code}): ${detail}`);
  }
  const live: ProviderProcessLiveDescriptor[] = [];
  for (const name of entries) {
    if (!name.endsWith('.json')) continue;
    const file = join(dir, name);
    const occupant = readSlotOccupant(file);
    if (slotReclaimable(occupant, file, now, staleMs)) {
      if (occupant.state !== 'missing' && sameSlotOccupant(readSlotOccupant(file), occupant)) {
        try { unlinkSync(file); } catch { /* racing reclaim is benign */ }
      }
      continue;
    }
    if (occupant.state !== 'valid') continue;
    live.push({
      pid: occupant.pid,
      startedAt: ownString(occupant.meta, 'startedAt') ?? '',
      host: ownString(occupant.meta, 'host') ?? '',
      storyId: ownString(occupant.meta, 'storyId'),
      agentType: ownString(occupant.meta, 'agentType') ?? '',
    });
  }
  return live;
}

function currentProcessStartTimeMs(): number {
  return Math.floor(Date.now() - process.uptime() * 1_000);
}

function sameProcessStart(left: number | undefined, right: number | undefined): boolean {
  if (left === undefined || right === undefined) return true;
  return Math.abs(left - right) <= 2_000;
}

// B-137a:F-124 — used at the classifyExistingLock wiring below, so NOT dead
// code; the `export` was the only dead part (no importer anywhere in
// packages/main/src or scripts). Narrowed to module-private.
function classifyProviderRegistryLock(snapshot: ExistingMkdirLockSnapshot): ExistingMkdirLockState {
  const holder = snapshot.holder;
  if (!holder || holder.hostname !== hostname()) return 'unknown';
  if (!Number.isInteger(holder.pid) || holder.pid <= 0) return 'unknown';
  try {
    process.kill(holder.pid, 0);
  } catch (error) {
    const code = (error as NodeJS.ErrnoException).code;
    if (code === 'ESRCH') return 'stale';
    if (code !== 'EPERM') return 'unknown';
  }
  if (
    holder.pid === process.pid
    && !sameProcessStart(holder.processStartTimeMs, currentProcessStartTimeMs())
  ) return 'stale';
  return 'active';
}

function withProviderRegistryLock<T>(
  dir: string,
  fn: () => T,
  timing: ProviderRegistryLockTiming = {},
): T {
  const lock = acquireMkdirLock(`${dir}.lock`, {
    label: 'provider-process-registry',
    deadlineMs: timing.deadlineMs ?? 30_000,
    staleMs: timing.staleMs ?? 10_000,
    pollMs: timing.pollMs ?? 10,
    requireHolderToken: true,
    classifyExistingLock: classifyProviderRegistryLock,
    holderInfo: {
      pid: process.pid,
      hostname: hostname(),
      command: 'provider-process-registry mutation',
      acquiredAt: new Date().toISOString(),
      lockId: randomUUID(),
      processStartTimeMs: currentProcessStartTimeMs(),
    },
  });
  try {
    return fn();
  } finally {
    lock.release();
  }
}

export function scanLiveProviderProcessSlots(
  dir: string,
  now: number,
  staleMs: number,
  lockTiming: ProviderRegistryLockTiming = {},
): ProviderProcessLiveDescriptor[] {
  return withProviderRegistryLock(dir, () => scanLiveProviderProcessSlotsUnlocked(dir, now, staleMs), lockTiming);
}

export function acquireProviderProcessSlot(
  dir: string,
  cap: number,
  staleMs: number,
  now: number,
  meta: ProviderProcessSlotMeta,
  lockTiming: ProviderRegistryLockTiming = {},
): AcquiredProviderProcessSlot | null {
  mkdirSync(dir, { recursive: true });
  const boundedCap = Number.isFinite(cap) && Number.isInteger(cap) && cap > 0
    ? cap
    : PROVIDER_PROCESS_MAX_CONCURRENT_DEFAULT;
  return withProviderRegistryLock(dir, () => {
    const live = scanLiveProviderProcessSlotsUnlocked(dir, now, staleMs);
    if (live.length >= boundedCap) return null;
    const token = randomUUID();
    const record: ProviderProcessSlotFileMeta = { ...meta, token };
    for (let index = 0; index < boundedCap; index += 1) {
      const file = join(dir, `slot-${index}.json`);
      if (writeProviderProcessSlotExclusive(file, record)) return { file, token };
      const judged = readSlotOccupant(file);
      if (!slotReclaimable(judged, file, now, staleMs)) continue;
      if (judged.state !== 'missing') {
        if (!sameSlotOccupant(readSlotOccupant(file), judged)) continue;
        try { unlinkSync(file); } catch { /* exclusive recreate decides the winner */ }
      }
      if (writeProviderProcessSlotExclusive(file, record)) return { file, token };
    }
    return null;
  }, lockTiming);
}

export function releaseProviderProcessSlot(
  file: string | null,
  token: string | null,
  lockTiming: ProviderRegistryLockTiming = {},
  mutationOps: ProviderRegistryMutationOps = DEFAULT_PROVIDER_REGISTRY_MUTATION_OPS,
): void {
  if (!file || !token) return;
  const dir = dirname(file);
  withProviderRegistryLock(dir, () => {
    const occupant = readSlotOccupant(file);
    if (occupant.state !== 'valid' || occupant.token !== token) return;
    mutationOps.unlink(file);
  }, lockTiming);
}

/**
 * B-137a F-119: BEST-EFFORT release for `finally` blocks.
 *
 * Two correct-but-opposed requirements meet here:
 *   1. A release failure must be OBSERVABLE, not a silent capacity leak --
 *      releaseProviderProcessSlot therefore throws, and a registry smoke pins
 *      that ("slot unlink mutation failure must be observable instead of
 *      silently leaking capacity").
 *   2. Every production release happens in a bare `finally` (host-run,
 *      autopilot-executor, codex-review-leaf, provider-process-admission), and
 *      a throw from `finally` REPLACES the in-flight exception -- hiding the
 *      real provider failure -- or turns a successful run into a hard error.
 *      host-run.ts's original releaseSlot wrapped its body in try/catch for
 *      exactly this reason; a refactor dropped that.
 *
 * Swallowing inside the primitive would satisfy (2) by destroying (1). So the
 * primitive keeps throwing and `finally` callers use this wrapper, which
 * reports the failure through onFailure instead of hijacking control flow.
 * Capacity is still reclaimable: pid-death detection and the orphan backstop
 * recover a leaked slot, whereas a masked exception is unrecoverable.
 */
export function releaseProviderProcessSlotBestEffort(
  file: string | null,
  token: string | null,
  onFailure: (error: unknown) => void = defaultReleaseFailureReporter,
  lockTiming: ProviderRegistryLockTiming = {},
  mutationOps: ProviderRegistryMutationOps = DEFAULT_PROVIDER_REGISTRY_MUTATION_OPS,
): void {
  try {
    releaseProviderProcessSlot(file, token, lockTiming, mutationOps);
  } catch (error) {
    // Never rethrow: this runs in finally. Reporting must not fail either.
    try {
      onFailure(error);
    } catch { /* a broken reporter must not mask the caller's exception */ }
  }
}

function defaultReleaseFailureReporter(error: unknown): void {
  const detail = error instanceof Error ? error.message : String(error);
  process.stderr.write(
    `⚠ provider process slot release failed (capacity is reclaimed by pid-death / orphan backstop): ${detail}\n`,
  );
}

export function transferProviderProcessSlotToProvider(
  file: string | null,
  token: string | null,
  identity: {
    pid: number;
    pgid: number | null;
    spawnedAt: string;
    startFingerprint: string | null;
    processGroupIsolated: boolean;
  },
  lockTiming: ProviderRegistryLockTiming = {},
): boolean {
  if (!file || !token) return false;
  if (
    !Number.isInteger(identity.pid) || identity.pid <= 0
    || !identity.processGroupIsolated
    || !Number.isInteger(identity.pgid) || (identity.pgid ?? 0) <= 0
  ) return false;
  const dir = dirname(file);
  return withProviderRegistryLock(dir, () => {
    const occupant = readSlotOccupant(file);
    if (occupant.state !== 'valid' || occupant.token !== token) return false;
    const next: ProviderProcessSlotFileMeta = {
      ...(occupant.meta as unknown as ProviderProcessSlotFileMeta),
      pid: identity.pid,
      providerPid: identity.pid,
      providerPgid: identity.pgid!,
      providerSpawnedAt: identity.spawnedAt,
      providerStartFingerprint: identity.startFingerprint ?? undefined,
      providerProcessGroupIsolated: true,
      token,
    };
    const temporary = `${file}.${token}.transfer`;
    writeFileSync(temporary, JSON.stringify(next), { encoding: 'utf8', flag: 'wx', mode: 0o600 });
    try {
      // Registry lock + exact token check makes this replacement ownership-safe.
      renameSync(temporary, file);
    } finally {
      try { unlinkSync(temporary); } catch { /* rename already consumed it */ }
    }
    return true;
  }, lockTiming);
}

export type ProviderExecutionSurfaceStatus =
  | 'managed'
  | 'admission_only'
  | 'adapter_only'
  | 'readiness_probe'
  | 'legacy_unmanaged';

export interface ProviderExecutionSurface {
  path: string;
  status: ProviderExecutionSurfaceStatus;
  admissionOwner: string | null;
  note: string;
}

/**
 * Conservative source classifier used by the contract smoke. Any production
 * file that imports a provider adapter, is itself an adapter, or combines a
 * child-process API with provider vocabulary must have an explicit inventory
 * row. False positives are classified, never silently excluded, so adding a
 * new direct provider spawn in a new file makes the contract fail closed.
 */
export function isProviderExecutionSurfaceCandidate(relativePath: string, source: string): boolean {
  if (!relativePath.endsWith('.ts')) return false;
  if (/(?:^|\/)(?:tasks|tests|generated)(?:\/|$)/.test(relativePath)) return false;
  if (relativePath === 'core/provider-process-registry.ts') return false;
  if (/^providers\/(?:codex-cli|claude-cli|gemini-cli)\.ts$/.test(relativePath)) return true;
  if (/providers\/(?:codex-cli|claude-cli|gemini-cli)\.js/.test(source)) return true;
  if (/\brunHostRun\s*\(/.test(source)) return true;
  // B-137a: strip documentation filename references before the provider-word
  // scan. The words are matched case-insensitively, so a prose citation of
  // "CLAUDE.md" (the project convention doc, referenced by many core modules)
  // read as a provider reference: any file that both used child_process for git
  // and cited that doc became an "unclassified provider execution surface".
  // scope-contract.ts tripped exactly this way on a comment citing the handler
  // convention -- a docs citation, not a provider workload. Several already
  // inventoried files (audit-scan, audit-trigger, rollout-check,
  // runtime-environment-checks) match for the same non-reason. Stripping only
  // "<provider>.md" filenames keeps every real provider reference intact,
  // including CLAUDE_CLI, claudeCli, 'claude' and providers/claude-cli.js.
  const withoutDocReferences = source.replace(/\b(?:codex|claude|agy|gemini|antigravity)\.md\b/gi, '');
  // B-137a: the provider word no longer requires a trailing \b. The old
  // /\bclaude\b/i missed identifier forms entirely -- `claudeCli`, `CLAUDE_CLI`,
  // `codexRunner` all failed to match, because \b does not break between two
  // word characters or before `_`. A file spawning a provider through such an
  // identifier was therefore invisible to this tripwire (verified against the
  // pre-change regex). A leading boundary is kept so unrelated substrings do not
  // match, but the tail is now open so identifier and member forms are caught.
  return /node:child_process/.test(source)
    && /\b(?:codex|claude|agy|gemini|antigravity)/i.test(withoutDocReferences);
}

