              root: ctx.root,
              storyId: proposal.storyId,
              agent: proposal.providerAgent,
              lane: proposal.lane,
              reviewRunId: proposal.reviewRunId,
              binding: candidate.binding,
              expected,
              evidence: candidate.evidence,
            });
            if (!existingVerification.valid) {
              throw new Error(`managed_review_evidence_import: existing imported evidence is no longer admissible (${existingVerification.reason})`);
            }
          }
          return { importedIds, binding: existingBinding, created: false };
        }

        const importedAt = intake.binding.importedAt;
        const binding = intake.binding;
        let importedIds: string[];
        if (proposal.conclusion === 'pass') {
          const data = ctx.store.readReviewPasses(proposal.storyId);
          const nextNum = data.passes.reduce((max, pass) => {
            const match = pass.id.match(/:RP-(\d+)$/);
            return match ? Math.max(max, Number(match[1])) : max;
          }, 0) + 1;
          const id = `${proposal.storyId}:RP-${String(nextNum).padStart(3, '0')}`;
          const provenance = {
            writerSessionId: `managed:${runId}`,
            sessionSource: 'managed-provider-import',
          };
          const pass: ReviewPass = {
            id,
            agent: proposal.lane,
            note: proposal.note!,
            createdAt: importedAt,
            reviewRound: story.currentReviewRound || '',
            reviewRunId: proposal.reviewRunId,
            ...(reviewRun.envelopeId ? { envelopeId: reviewRun.envelopeId } : {}),
            writerSessionId: provenance.writerSessionId,
            sessionSource: provenance.sessionSource,
            readManifest: proposal.readManifest,
            ...(proposal.readLog ? { readLog: proposal.readLog } : {}),
            ...(proposal.readDiagnostics ? { readDiagnostics: proposal.readDiagnostics } : {}),
            managedEvidenceBinding: binding,
            _hash: signReviewPass(
              proposal.storyId,
              id,
              proposal.lane,
              proposal.note!,
              importedAt,
              story.currentReviewRound || '',
              proposal.reviewRunId,
              proposal.readManifest,
              proposal.readLog,
              proposal.readDiagnostics,
              provenance,
              reviewRun.envelopeId,
              binding,
            ),
          };
          data.passes.push(pass);
          assertLiveReviewMaterial();
          ctx.store.writeReviewPasses(proposal.storyId, data);
          // Persist the receipt-owned evidence identity before sealing its
          // immutable external binding. A crash in the opposite order left a
          // binding for an as-yet-unwritten RP id; another receipt could then
          // allocate that id, making the authentic retry irreconcilable.
          // The existing-evidence branch above repairs the inverse crash
          // window (story persisted, binding not yet sealed) idempotently.
          assertLiveReviewMaterial();
          writeManagedHostRunEvidenceBinding(ctx.root, runId, {
            schemaVersion: 'lattice.managed_review_evidence_import.v1',
            runId,
            receiptId,
            storyId: proposal.storyId,
            reviewRunId: proposal.reviewRunId,
            lane: proposal.lane,
            importedIds: [id],
            importedAt: binding.importedAt,
          });
          importedIds = [id];
        } else {
          const data = ctx.store.readFindings(proposal.storyId);
          const start = data.findings.reduce((max, finding) => {
            const match = finding.id.match(/:F-(\d+)$/);
            return match ? Math.max(max, Number(match[1])) : max;
          }, 0);
          const findings: Finding[] = proposal.findings!.map((candidate, index) => {
            const id = `${proposal.storyId}:F-${String(start + index + 1).padStart(3, '0')}`;
            const findingBinding: ManagedReviewEvidenceBinding = { ...binding, proposalFindingIndex: index };
            const finding: Finding = {
              id,
              desc: candidate.desc,
              severity: candidate.severity,
              category: candidate.category,
              status: 'open',
              evidenceState: candidate.evidenceState ?? 'verified',
              ...(candidate.uncertaintyReason ? { uncertaintyReason: candidate.uncertaintyReason } : {}),
              agent: proposal.lane,
              createdAt: importedAt,
              reviewRound: story.currentReviewRound || '',
              reviewRunId: proposal.reviewRunId,
              readManifest: proposal.readManifest,
              ...(proposal.readLog ? { readLog: proposal.readLog } : {}),
              ...(proposal.readDiagnostics ? { readDiagnostics: proposal.readDiagnostics } : {}),
              ...(candidate.files ? { files: candidate.files } : {}),
              managedEvidenceBinding: findingBinding,
              _hash: signFinding(
                proposal.storyId,
                id,
                candidate.desc,
                candidate.severity,
                importedAt,
                story.currentReviewRound || '',
                proposal.reviewRunId,
                proposal.readManifest,
                proposal.readLog,
                proposal.readDiagnostics,
                undefined,
                findingBinding,
              ),
            };
            return finding;
          });
          const findingIds = findings.map(finding => finding.id);
          data.findings.push(...findings);
          assertLiveReviewMaterial();
          ctx.store.writeFindings(proposal.storyId, data);
          // Keep the multi-finding conclusion on the same recovery ordering as
          // review passes: durable story evidence first, immutable receipt seal
          // second. Retry then repairs an absent seal from the exact persisted
          // evidence instead of allocating a fresh conflicting id set.
          assertLiveReviewMaterial();
          writeManagedHostRunEvidenceBinding(ctx.root, runId, {
            schemaVersion: 'lattice.managed_review_evidence_import.v1',
            runId,
            receiptId,
            storyId: proposal.storyId,
            reviewRunId: proposal.reviewRunId,
            lane: proposal.lane,
            importedIds: findingIds,
            importedAt: binding.importedAt,
          });
          importedIds = findingIds;
        }
        return { importedIds, binding, created: true };
      }, { label: `managed review ${proposal.conclusion} metadata` }));

      const { importedIds, created } = importResult;
      if (!created) {
        return `Managed review evidence already imported from ${runId}: ${importedIds.join(', ')}`;
      }
      ctx.store.appendProcessEvent(proposal.storyId, {
        type: proposal.conclusion === 'pass' ? 'review_pass' : 'reviewer_finding',
        storyId: proposal.storyId,
        command: 'managed_review_evidence_import',
        role: 'reviewer',
        agent: proposal.lane,
        result: 'pass',
        managedRunId: runId,
        managedReceiptId: receiptId,
        importedIds,
        readManifest: proposal.readManifest,
        ...(proposal.readLog ? { readLog: proposal.readLog } : {}),
      });
      const commitHint = autoCommitStoryMetadata(ctx.root, proposal.storyId, 'managed_review_evidence_import');
      return `Managed review evidence imported from ${runId}: ${importedIds.join(', ')}${commitHint}`;
    },
  };
}
      // stdout stays clean for the JSON result. Each chunk write is settle-aware
      // (write + counted callback) but NOT awaited, so throughput is never
      // serialized. A SYNCHRONOUS write failure is still thrown through to the CORE
      // guard (F-008: delivery stops, the run still completes, passthroughError
      // surfaces); an ASYNCHRONOUS 'error' recorded via the callback/listener flips
      // asyncStreamError so the NEXT chunk throws through instead of hammering a dead
      // pipe (F-020).
      const passthrough: HostRunPassthrough = (chunk: HostRunChunk) => {
        if (asyncStreamError !== null) {
          // The stream already emitted an async 'error' — the pipe is gone. Throw
          // through (the same contract as a sync write failure) so the core flips
          // its passthrough-broken flag instead of writing to a broken stream.
          throw new Error(asyncStreamError);
        }
        const toStderr = json || chunk.stream === 'stderr';
        const streamName: 'stdout' | 'stderr' = toStderr ? 'stderr' : 'stdout';
        // Skip a stream already known broken (honest degradation; passthroughError
        // already records the failure) — never queue a fresh write onto a dead pipe.
        if (toStderr ? stderrBroken : stdoutBroken) return;
        const stream = toStderr ? stderr : stdout;
        pendingWrites += 1;
        pendingWritesByStream[streamName] += 1;
        try {
          stream.write(chunk.text, (err) => {
            if (err) recordStreamError(streamName)(err);
            settleWrite(streamName);
          });
        } catch (err) {
          // Rare synchronous throw (e.g. write-after-end): settle the counter, then
          // throw through so the core flips its passthrough-broken flag (F-008).
          settleWrite(streamName);
          throw err instanceof Error ? err : new Error(`host_run passthrough write failed: ${String(err)}`);
        }
      };

      // F-020 / F-023 / F-024: gated, SETTLE-AWARE stderr diagnostics that also join
      // the pendingWrites accounting. Never write to a stderr already known broken
      // (avoids a late async EPIPE 'error' firing with no listener). When we DO
      // write, the promise resolves on the write CALLBACK and the SAME callback
      // decrements the shared counter — so both the per-call await (F-023) AND the
      // unified drainPending() (F-024) cover this write. The crux F-023 case is a
      // quiet text-mode run whose stderr is already closed, where this final usage
      // line is the FIRST stderr write (stderrBroken never opened, nothing skipped
      // it). A callback/synchronous error folds into the SAME broken/async-error
      // state (recordStreamError via onStderrError) and is swallowed — best-effort
      // diagnostics must never turn a completed run into a crash (F-008 contract).
      const emitStderr = (text: string): Promise<void> => {
        if (stderrBroken) return Promise.resolve();
        return new Promise<void>((resolve) => {
          pendingWrites += 1;
          pendingWritesByStream.stderr += 1;
          try {
            stderr.write(text, (err) => {
              if (err) onStderrError(err);
              settleWrite('stderr');
              resolve();
            });
          } catch (err) {
            // Rare synchronous throw — flip broken state and settle.
            onStderrError(err);
            settleWrite('stderr');
            resolve();
          }
